// Concatenates supabase/migrations/*.sql (in order) into supabase/full-schema.sql,
// a single script to paste into the Supabase SQL editor on a NEW, empty project.
// Usage: npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const header = `-- =============================================================================
-- Element — full database schema (generated by \`npm run db:bundle\`; do not edit).
-- Source: ${files.length} migrations in supabase/migrations, applied in order.
--
-- Run ONCE on a NEW, empty Supabase project (SQL editor). Running it on a project
-- that already has these objects fails (tables already exist).
-- After running it, complete the steps at the end of this file (Vault secrets).
-- =============================================================================

`;

const body = files
  .map((f) => `-- -----------------------------------------------------------------------------\n-- Migration: ${f}\n-- -----------------------------------------------------------------------------\n\n${readFileSync(join(dir, f), "utf8").trim()}\n`)
  .join("\n");

const footer = `
-- =============================================================================
-- NEXT STEPS (not part of the schema; run separately, with your own values):
--
-- 1) Deploy the purge function and set its secret (terminal):
--      npx supabase functions deploy purge-trash --no-verify-jwt
--      npx supabase secrets set PURGE_TRASH_SECRET=<random value, 48+ characters>
--
-- 2) Store the Vault secrets used by the daily purge job (SQL editor):
--      select vault.create_secret('https://<project-ref>.supabase.co/functions/v1/purge-trash', 'purge_trash_url');
--      select vault.create_secret('<same PURGE_TRASH_SECRET>', 'purge_trash_secret');
--
-- 3) Create the first administrator from your machine: npm run admin:create
-- =============================================================================
`;

writeFileSync("supabase/full-schema.sql", header + body + footer);
console.log(`supabase/full-schema.sql written (${files.length} migrations)`);
